// Extract Zoom event data
const body = items[0].json;
const event = body.event || '';

if (event === 'meeting.participant_joined' || event === 'meeting.participant_left') {
  const participant = body.payload?.object?.participant || {};
  const meeting = body.payload?.object || {};
  const displayName = participant.user_name || '';
  const meetingId = String(meeting.id || '');
  const topic = meeting.topic || 'Untitled Session';

  // Parse Name_MatrixNumber format
  let name = '';
  let matrixNumber = '';
  let isValidFormat = false;
  let formatError = '';

  if (displayName.includes('_')) {
    const parts = displayName.split('_', 2);
    name = parts[0].trim();
    matrixNumber = parts[1]?.trim() || '';

    if (name.length >= 2 && /^[a-zA-Z\s]+$/.test(name) && /^\d{6,12}$/.test(matrixNumber)) {
      isValidFormat = true;
      name = name.charAt(0).toUpperCase() + name.slice(1).toLowerCase();
    } else {
      formatError = `Name or matrix invalid: name='${name}', matrix='${matrixNumber}'`;
    }
  } else {
    formatError = 'Missing underscore separator. Expected: Name_MatrixNumber';
  }

  return [{
    json: {
      name: name,
      matrix_number: matrixNumber,
      meeting_id: meetingId,
      topic: topic,
      display_name: displayName,
      join_time: participant.join_time || new Date().toISOString(),
      leave_time: participant.leave_time || null,
      is_valid_format: isValidFormat,
      format_error: formatError,
      event_type: event === 'meeting.participant_joined' ? 'participant_joined' : 'participant_left',
      processed_at: new Date().toISOString()
    }
  }];
}

// Ignore other events
return [{ json: { event_type: 'ignored', original_event: event } }];
